"""Writes docs/research/recall_diagnosis.md from reports/ai/recall-*.json: `tools/.venv/Scripts/python.exe tools/bench/recall_report.py [--check]` (ADR-0022 follow-up). Every number on the page comes from those files; counts keep their denominators."""
from __future__ import annotations

import json
import sys
from collections import Counter
from pathlib import Path

sys.stdout.reconfigure(encoding="utf-8")
ROOT = Path(__file__).resolve().parents[2]
R = ROOT / "reports" / "ai"
OUT = ROOT / "docs" / "research" / "recall_diagnosis.md"
SPLITS = ("dev", "test", "test2")
VERDICT = {
    "CRITICAL_MASS_CAP": "incorrect rejection; recoverable only below the new cap (see the mass bands), otherwise a deliberate safety trade",
    "WRONG_ACT": "semantic confusion between two acts (some pairs are rubric tie-breaks: ambiguous label)",
    "CRITICAL_CUE": "conservative rejection by a regular-expression cue; the sentence is ambiguous with a critical-content wording",
    "HEADS_DISAGREE": "the second reader (words) names another act; an independent safety layer, kept",
    "BELOW_THRESHOLD": "below the act's calibrated threshold; kept",
    "TOP_IS_NONE": "the head reads the sentence as small talk or noise; a classifier miss",
    "TOP_IS_CRITICAL_ACT": "the head reads the sentence as a critical act; a classifier miss that is also a safety refusal",
    "ENGINE_LOW_CONFIDENCE": "incorrect rejection DOWNSTREAM: the engine's evidence store refused evidence the gate had credited (placeholder 0.8 threshold); fixed",
}


def j(name: str) -> dict:
    return json.loads((R / name).read_text(encoding="utf-8"))


def ratio(a: str) -> tuple[int, int]:
    x, y = a.split("/")
    return int(x), int(y)


def render() -> str:
    diag = {s: j(f"recall-diagnosis-{s}.json") for s in SPLITS}
    ship = {s: j(f"recall-diagnosis-{s}-shipped.json") for s in SPLITS}
    ev = {s: {c["candidate"]: c for c in j(f"recall-eval-{s}.json")["candidates"]} for s in SPLITS}
    conf = {s: j(f"recall-confirm-{s}.json")["candidates"][0] for s in ("test", "test2")}
    panel = j("recall-safety-panel.json")["cap_variants"]
    adiff = j("recall-assertion-diff.json")
    frozen = j("../../tools/bench/recall_frozen.json") if False else json.loads((ROOT / "tools" / "bench" / "recall_frozen.json").read_text(encoding="utf-8"))
    rev = json.loads((ROOT / "tools" / "bench" / "recall_cap_revision.json").read_text(encoding="utf-8"))
    names = list(ev["dev"])
    base, chosen = names[0], frozen["chosen"]
    pct = sorted(round(100 * diag[s]["primary_cause_of_missed"].get("CRITICAL_MASS_CAP", 0) / diag[s]["missed"]) for s in SPLITS)
    sole = sorted(round(100 * diag[s]["only_blocker_of_missed"].get("CRITICAL_MASS_CAP", 0) / diag[s]["missed"]) for s in SPLITS)
    leak_masses = sorted(x for v in panel["cap removed"].values() for x in v["leak_masses"])
    still = sorted(round(100 * ship[s]["missed"] / ship[s]["legitimate_rows"]) for s in SPLITS)
    L = ["# Why legitimate speech is missed, and what was changed (ADR-0022 follow-up)", "",
         "_Generated by `tools/bench/recall_report.py` from `reports/ai/recall-*.json`; do not edit by hand. **PRELIMINARY: synthetic.** `tests/action_bench_v1` is written by one author family and labelled by construction; the safety panel and the regression sentences are builder-written; none of it is independent evidence, and speech-based scoring stays OFF._", "",
         "## What was asked, how the evidence was kept honest", "",
         "* Every legitimate row (status actual, categories paraphrase and asr_error: 140 per split) is traced through the stages of the path in production order (transcript, context, candidate generation, critical-mass cap, per-act threshold, critical-content cue, second reader, assertion layer, status and context rules, and finally the ENGINE's evidence store, run by the CLI command `evidence-check`, not by a Python copy of its rules). `tools/bench/recall_diagnosis.py`.",
         "* The causes and the fixes were chosen on the **dev** split and on the safety panel. The candidate set and the selection rule were frozen in `tools/bench/recall_frozen.json` before the held-out splits (`test`, `test2`) were scored; they were then scored once per candidate (`recall-eval-<split>.json`, locked). The causes on test and test2 below were traced after the freeze, to confirm the dev picture, not to choose anything.",
         "* **What was seen:** the whole safety panel (including challenge v6) was used when the cap value was chosen, so none of it is unseen; the AI-judged v2 counts were printed with the dev run, so v2 test is corroboration, not a held-out claim. The only unseen data are the action_bench test and test2 splits. After the freeze, assertion-layer holes were found by hand-written counterexamples and closed; the shipped configuration was re-scored on test and test2 as a labelled second look (`recall-confirm-<split>.json`) and accepted exactly the same sentences as the frozen run.", ""]
    # ---------------------------------------------------------------- 1 the claim
    L += ["## 1. Is the critical-mass cap the cause of most misses? (traced, not assumed)", "",
          "Baseline = the path as pushed in `2f9aa0a`: cap 0.03, the engine's 0.8 placeholder threshold. A row is MISSED unless the engine accepted evidence for the right act.", "",
          "| Split | Legitimate rows | Accepted by the engine (right act) | Missed | Cap is the PRIMARY cause | Cap is the ONLY blocker | Cap is one of the blockers | Label is the top act and the cap fired |", "|---|---|---|---|---|---|---|---|"]
    for s in SPLITS:
        d = diag[s]
        p = d["primary_cause_of_missed"].get("CRITICAL_MASS_CAP", 0)
        L.append(f"| {s}{' (causes chosen here)' if s == 'dev' else ' (traced after the freeze)'} | {d['legitimate_rows']} | {d['right']} | {d['missed']} | {p} ({round(100 * p / d['missed'])}%) | {d['only_blocker_of_missed'].get('CRITICAL_MASS_CAP', 0)} | {d['any_blocker_of_missed'].get('CRITICAL_MASS_CAP', 0)} | {d['cap_vs_top_act'].get('label_is_top / cap_hit', 0)} |")
    L += ["", f"**Confirmed, with a qualification.** The cap is the primary blocker of {pct[0]} to {pct[-1]} percent of the misses and the only blocker of {sole[0]} to {sole[-1]} percent of them. But it is not an unnecessary restriction: with it removed, {len(leak_masses)} sentences of evasive critical content or non-performed speech are offered, with critical masses from {leak_masses[0]} to {leak_masses[-1]} (section 3). Many blocked legitimate sentences carry the same critical mass as those {len(leak_masses)}, and no other signal the path has separates them.", "",
          "### Primary cause of every missed row", "", "| Cause | " + " | ".join(f"{s} baseline" for s in SPLITS) + " | " + " | ".join(f"{s} shipped" for s in SPLITS) + " | Judgement |", "|---|" + "---|" * 7]
    causes = sorted({c for d in list(diag.values()) + list(ship.values()) for c in d["primary_cause_of_missed"]}, key=lambda c: (-sum(d["primary_cause_of_missed"].get(c, 0) for d in diag.values()), c))
    for c in causes:
        L.append(f"| {c} | " + " | ".join(str(diag[s]["primary_cause_of_missed"].get(c, 0)) for s in SPLITS) + " | " + " | ".join(str(ship[s]["primary_cause_of_missed"].get(c, 0)) for s in SPLITS) + f" | {VERDICT.get(c, '')} |")
    L += ["", "Rows are counted once, under the first blocker in production order; a wrong top act is its own cause. The full list of blockers per row, the per-act recall and the traces of every row are in `reports/ai/recall-diagnosis-<split>[-shipped].json`.", "",
          "### Representative examples (dev, baseline)", "", "| Cause | Sentence | Label | Head's top act (probability) | Critical mass | Other blockers |", "|---|---|---|---|---|---|"]
    seen = Counter()
    for t in diag["dev"]["traces"]:
        if t["missed"] and seen[t["primary"]] < 2:
            seen[t["primary"]] += 1
            L.append(f"| {t['primary']} | {t['text']} | {t['label']} | {t['top']} ({t['p_top']}) | {t['mass']} | {', '.join(b for b in t['blockers'] if b != t['primary']) or '-'} |")
    # mass bands
    L += ["", "### Critical mass of the dev rows the cap blocked (label was the top act)", "", "| Critical mass | Rows | Meaning |", "|---|---|---|"]
    capped = [t for t in diag["dev"]["traces"] if t["missed"] and t["primary"] == "CRITICAL_MASS_CAP" and t["top"] == t["label"]]
    band = lambda lo, hi: sum(1 for t in capped if lo <= t["mass"] < hi)  # noqa: E731
    L += [f"| 0.03 to under 0.05 | {band(0.03, 0.05)} | no longer blocked by the new cap ({len(ev['dev'][chosen]['vs_baseline']['newly_accepted_right'])} dev rows end up accepted in all; the others have another blocker) |", f"| 0.05 to under {leak_masses[0]} | {band(0.05, leak_masses[0])} | below every unsafe sentence found; not recovered, a margin kept |",
          f"| 0.0757 and above | {band(leak_masses[0], 9)} | at the critical mass of the unsafe sentences (the nearest is {leak_masses[0]}): not recoverable with the signals the path has |", ""]
    # ---------------------------------------------------------------- 2 downstream
    d0, d1 = ev["dev"][base], ev["dev"][chosen]
    L += ["## 2. A downstream rejection the benchmark did not show", "",
          "`content/assessment/mapping.json` carried one engine threshold, 0.8 for every act, marked \"the guide's example, replaced by the calibration export when one exists\". The classifier's own calibrated thresholds range from 0.15 to 0.75 and no export was ever made, so the engine's evidence store refused evidence the gate had credited. "
          "Earlier benchmark pages counted what the service OFFERED; these numbers count what the ENGINE ACCEPTS:", "",
          "| Split | Offered by the service (baseline) | Accepted by the engine | Refused (LOW_CONFIDENCE) |", "|---|---|---|---|"]
    for s in SPLITS:
        b = ev[s][base]["bench"]
        L.append(f"| {s} | {b['true_positive_accepted'] + b['right_act_offered_but_refused_by_engine'] + b['wrong_act_accepted']} | {b['true_positive_accepted'] + b['wrong_act_accepted']} | {b['right_act_offered_but_refused_by_engine']} |")
    L += ["", f"Fix (`tools/content/build_scoring.py`): the engine's per-act thresholds are the head's calibrated thresholds floored to three decimals, so the engine never refuses what the gate credited at its own threshold and never accepts below it. Isolated effect: dev {d0['bench']['true_positive_accepted']} to {ev['dev']['engine calibrated only']['bench']['true_positive_accepted']}, test {ev['test'][base]['bench']['true_positive_accepted']} to {ev['test']['engine calibrated only']['bench']['true_positive_accepted']}, test2 {ev['test2'][base]['bench']['true_positive_accepted']} to {ev['test2']['engine calibrated only']['bench']['true_positive_accepted']}. "
          f"It matters more once the cap is relaxed: with the cap at 0.05 and the placeholder kept, the engine would refuse {ev['dev']['cap 0.05, engine default']['bench']['right_act_offered_but_refused_by_engine']} (dev), {ev['test']['cap 0.05, engine default']['bench']['right_act_offered_but_refused_by_engine']} (test) and {ev['test2']['cap 0.05, engine default']['bench']['right_act_offered_but_refused_by_engine']} (test2) correct offers.", ""]
    # ---------------------------------------------------------------- 3 cap vs safety
    L += ["## 3. The safety panel and the cap", "",
          f"Every existing set of evasive critical sentences and non-performed speech ({sum(v['rows'] for v in panel['cap 0.03 (shipped)'].values())} sentences, `tools/bench/recall_safety_panel.py`), in the MOST PERMISSIVE context (every step running, a question and a read-back waiting), through the whole path. A leak is a sentence the path offers as evidence.", "",
          "| Set (status) | Rows | Leaks: cap 0.03 | cap 0.05 (shipped) | cap 0.10 | cap removed |", "|---|---|---|---|---|---|"]
    v3, v5, v10, v0 = panel["cap 0.03 (shipped)"], panel["cap 0.05"], panel["cap 0.10"], panel["cap removed"]
    for name, v in v3.items():
        L.append(f"| {name} | {v['rows']} | {v['leaks']} | {v5[name]['leaks']} | {v10[name]['leaks']} | {v0[name]['leaks']} |")
    L += ["", f"Total leaks: cap 0.03 {sum(v['leaks'] for v in v3.values())}, cap 0.05 {sum(v['leaks'] for v in v5.values())}, cap 0.10 {sum(v['leaks'] for v in v10.values())}, cap removed {sum(v['leaks'] for v in v0.values())}. The sentences that leak without the cap, with the critical mass the head gives them, are in the regression fixture (`tests/classifier_regression/recall_cases.json`, group `cap_blocked_unsafe`).",
          f"The margin: the nearest of those has critical mass {leak_masses[0]}, {round(leak_masses[0] / rev['to'], 2)} times the new cap. **Rule used (frozen):** {frozen['selection_rule']}", "",
          f"**Caveat.** The head's own tuning table recorded one misroute at 0.05 on the AI-judged v2 dev split when it was built; on the saved head it re-measures as {panel['cap 0.05']['tuned-on: AI-judged v2 dev critical-labelled rows']['leaks']} of {panel['cap 0.05']['tuned-on: AI-judged v2 dev critical-labelled rows']['rows']} (revision block in `content/assessment/act_head_hybrid.json`). The panel is synthetic and builder-written; a margin of 1.5 times is not a guarantee. Rollback is one value (`tools/bench/recall_frozen.json`).", ""]
    # ---------------------------------------------------------------- 4 candidates
    L += ["## 4. Candidates on identical rows, counting evidence accepted by the engine", "",
          "| Split | Candidate | Right (TP) | Missed (FN) | Wrong act accepted (FP) | Credited precision | Refused by the engine | Critical / non-assertive / out-of-window accepted | Panel leaks accepted |", "|---|---|---|---|---|---|---|---|---|"]
    for s in SPLITS:
        for n in names:
            c = ev[s][n]
            b = c["bench"]
            L.append(f"| {s}{' (selection)' if s == 'dev' else ' (held-out, scored once)'} | {n}{' **(chosen)**' if n == chosen else ''} | {b['true_positive_accepted']}/{b['legit_rows']} | {b['false_negative']} | {b['wrong_act_accepted']} | {b['credited_precision']} | {b['right_act_offered_but_refused_by_engine']} | {b['critical_accepted']} / {b['non_assertive_accepted']} / {b['out_of_window_own_act_accepted']} | {sum(v['accepted_by_engine'] for v in c['panel'].values())} |")
    L += ["", "Shipped configuration (the chosen candidate plus the assertion fixes of section 6), re-scored on the held-out splits as a labelled SECOND LOOK:", "", "| Split | Right (TP) | Missed (FN) | Wrong act | Credited precision | Critical / non-assertive / out-of-window | Same accepted sentences as the frozen run |", "|---|---|---|---|---|---|---|"]
    for s in ("test", "test2"):
        c = conf[s]
        b = c["bench"]
        same = c["_accepted_ids"] == ev[s][chosen]["_accepted_ids"]
        L.append(f"| {s} | {b['true_positive_accepted']}/{b['legit_rows']} | {b['false_negative']} | {b['wrong_act_accepted']} | {b['credited_precision']} | {b['critical_accepted']} / {b['non_assertive_accepted']} / {b['out_of_window_own_act_accepted']} | {'yes' if same else 'NO'} |")
    ctxacts = ("ANSWER_QUESTION", "CLOSED_LOOP")
    L += ["", "### Recall by communication act, and without the two acts that need waiting context", "",
          "ANSWER_QUESTION and CLOSED_LOOP are offered only with a waiting patient question or a critical result awaiting acknowledgement. The benchmark ASSUMES that context for those rows; the engine records the second rarely. The gain is therefore also given without them, so it is not credited to an assumption.", "",
          "| Split | All acts: baseline to shipped | Without ANSWER_QUESTION and CLOSED_LOOP: baseline to shipped |", "|---|---|---|"]
    for s in SPLITS:
        a, b = ev[s][base]["bench"]["recall_by_act"], ev[s][chosen]["bench"]["recall_by_act"]
        tot = lambda m, skip=(): (sum(ratio(v)[0] for k, v in m.items() if k not in skip), sum(ratio(v)[1] for k, v in m.items() if k not in skip))  # noqa: E731
        L.append(f"| {s} | {tot(a)[0]}/{tot(a)[1]} to {tot(b)[0]}/{tot(b)[1]} | {tot(a, ctxacts)[0]}/{tot(a, ctxacts)[1]} to {tot(b, ctxacts)[0]}/{tot(b, ctxacts)[1]} |")
    L += ["", "Per act (dev, baseline to shipped): " + ", ".join(f"{k} {ev['dev'][base]['bench']['recall_by_act'][k]} to {v}" for k, v in ev["dev"][chosen]["bench"]["recall_by_act"].items()) + ".", "",
          f"Newly accepted right sentences on dev ({len(ev['dev'][chosen]['vs_baseline']['newly_accepted_right'])}; none lost): " + "; ".join(f"\"{t}\"" for t in [x["text"] for x in diag["dev"]["traces"] if x["id"] in ev["dev"][chosen]["vs_baseline"]["newly_accepted_right"]]) + ".",
          f"Wrong-act acceptances: dev {len(ev['dev'][chosen]['_wrong'])} (" + "; ".join(f"\"{w['text']}\" labelled {w['label']}, accepted as {w['accepted_as']}" for w in ev["dev"][chosen]["_wrong"]) + f"), test {len(ev['test'][chosen]['_wrong'])}, test2 {len(ev['test2'][chosen]['_wrong'])}. The dev one is a rubric tie-break between EXPLAIN_PROCEDURE and EXPLAIN_ACTION (an ambiguous label).", "",
          "### The AI-judged v2 ordinary rows (a second author family; labels from AI judges; the counts were seen with the dev run, so corroboration only)", "", "| Candidate | v2 dev right / rows (wrong act) | v2 test right / rows (wrong act) |", "|---|---|---|"]
    for n in names:
        v = ev["dev"][n]["v2_ordinary"]
        L.append(f"| {n} | {v['dev']['true_positive_accepted']}/{v['dev']['rows']} ({v['dev']['wrong_act_accepted']}) | {v['test']['true_positive_accepted']}/{v['test']['rows']} ({v['test']['wrong_act_accepted']}) |")
    # ---------------------------------------------------------------- 5 what was rejected as a fix
    L += ["", "## 5. Causes examined and deliberately NOT changed", "",
          "* **Regular-expression cue false positives (dev: 4 rows, e.g. \"I would like a chest x ray requested\", \"I would like the senior doctor to see him\").** The cue `i would like (the|a|someone)` is broad, but these sentences are genuinely ambiguous with an SBAR recommendation (\"I would like the anaesthetist to review before theatre\", an approved positive example of a critical act). Narrowing a critical-content floor on two synthetic sentences would be tuning to the benchmark; left as a conservative rejection.",
          "* **ASR-style fused words (\"onthe\", \"theporter\", \"feelanxious\").** The benchmark's seeded damage drops spaces; real recognisers (Whisper) substitute words, they rarely fuse them. A word-segmentation repair would exploit that artifact; not done.",
          f"* **Context-constrained re-ranking (promote the best ELIGIBLE act when the head's top act is not eligible).** Examined on dev: {sum(1 for t in diag['dev']['traces'] if t['missed'] and 'TOP_NOT_ELIGIBLE' in t['blockers'])} missed rows have a top act that is not eligible in the row's state, and {sum(1 for t in ship['dev']['traces'] if t['missed'] and 'TOP_NOT_ELIGIBLE' in t['blockers'] and t['mass'] < rev['to'])} of them would be reachable at the shipped cap, so the change would recover nothing on dev while adding a way for a critical sentence to be turned into an ordinary act. Not done.",
          "* **Per-act or ratio-based caps, and the second head's critical mass.** The TF-IDF head's critical mass does not separate the blocked legitimate rows from the unsafe ones (the ranges overlap completely above the nearest unsafe sentence); a per-act cap would be fitted to a handful of unsafe sentences. Not done.",
          "* **Per-act thresholds (BELOW_THRESHOLD, e.g. REPORT_FAULT 0.747).** Calibrated for credited precision 0.8 on a different dev set (ADR-0016); not touched.",
          "* **Another model or technique.** None was run: no diagnosed failure needs one that a targeted experiment could change. The remaining category (a legitimate sentence whose critical mass equals that of unsafe speech) needs a better critical-content signal; that is a question for the independent set (EX-01).", ""]
    # ---------------------------------------------------------------- 6 assertion
    sets_ = adiff["sets"]
    cx = sets_["regression: counterexamples (denied, plan, hypothetical, reported, other speaker, broken off)"]
    L += ["## 6. Holes in the assertion layer found by counterexamples, and closed", "",
          f"For 14 acts, hand-written legitimate paraphrases were paired with a denial, a plan, a hypothetical, a report, another speaker and a broken-off sentence ({cx['sentences']} counterexamples). The layer before the fixes (`{adiff['before']}`) caught {cx['flagged_before']} of them; the classifier refused some of the rest by luck and the critical-mass cap hid others. Found:", "",
          "* **Other speakers.** Four patterns each carried its own short list of roles, so \"The technician will report the monitor fault\" and \"The radiographer will explain the scan to you\" were credited. One shared list of ward, theatre, laboratory and imaging roles now serves all of them.",
          "* **Plans.** \"I'll order the ECG after the handover\", \"I'll call the senior in a few minutes\", \"I'll explain the operation once you have signed\" were credited: the delay markers were a handful of words. They are widened to a class (after the/this/that, in a few minutes, tomorrow, once I/you have, and similar). \"I will tell you when it is in\" and \"I will call you when the porter arrives\" are read-backs and keep their credit.",
          "* **Conditionals.** \"If the suction were broken I would report it\", \"If you asked how long it takes, I would say about an hour\", \"If I asked you to say it back, could you?\" were credited. A sentence that opens with if and states what the speaker would do, or asks what the listener would, is now hypothetical. \"What would you like me to explain?\" and \"If you have any questions, I will answer them\" keep their credit.",
          "* **Denials with \"say\".** \"I didn't say you looked worried\" was not a denial (only \"haven't\" and similar were).", "",
          "| Sentences | Count | Flagged before | Flagged now | Newly flagged |", "|---|---|---|---|---|"]
    for k, v in sets_.items():
        L.append(f"| {k} | {v['sentences']} | {v['flagged_before']} | {v['flagged_now']} | {v['newly_flagged']} |")
    L += ["", f"**Legitimate sentences newly flagged by the fixes: {adiff['legitimate_sentences_newly_flagged']}.** (A first version of the plan markers also flagged a legitimate read-back that ended \"and I'll recheck in an hour\"; \"hours\" was dropped from the markers and the diff re-run.) These fixes only remove credit; they changed no accepted sentence on dev, test or test2. The cap relaxation needed them first: before the fixes more counterexamples were offered at cap 0.05 than at 0.03, because the cap had been hiding some of these holes.", "",
          "## 7. Remaining failure categories (shipped configuration)", "", "| Cause | " + " | ".join(SPLITS) + " | Why it remains |", "|---|---|---|---|---|"]
    rem = sorted({c for d in ship.values() for c in d["primary_cause_of_missed"]}, key=lambda c: (-sum(d["primary_cause_of_missed"].get(c, 0) for d in ship.values()), c))
    why = {"CRITICAL_MASS_CAP": "critical mass at or above 0.05: the same as unsafe sentences; needs a better critical-content signal and the independent set", "WRONG_ACT": "act confusion (read-back against answer or order, explanation against action, the head's top act is another act)",
           "CRITICAL_CUE": "ambiguous with a critical-content wording", "HEADS_DISAGREE": "the word reader disagrees, mostly on recogniser-style text", "BELOW_THRESHOLD": "below the act's calibrated threshold", "TOP_IS_NONE": "read as small talk or noise",
           "TOP_IS_CRITICAL_ACT": "read as critical content; a safety refusal"}
    for c in rem:
        L.append(f"| {c} | " + " | ".join(f"{ship[s]['primary_cause_of_missed'].get(c, 0)}/{ship[s]['missed']}" for s in SPLITS) + f" | {why.get(c, '')} |")
    L += ["", "## 8. What this does and does not show", "",
          f"* **Recall genuinely improved on the held-out synthetic splits without a measured safety cost:** accepted right sentences {ev['test'][base]['bench']['true_positive_accepted']} to {conf['test']['bench']['true_positive_accepted']} of 140 (test) and {ev['test2'][base]['bench']['true_positive_accepted']} to {conf['test2']['bench']['true_positive_accepted']} of 140 (test2), credited precision {conf['test']['bench']['credited_precision']} and {conf['test2']['bench']['credited_precision']}, no critical, non-assertive or out-of-window evidence accepted, no panel sentence accepted. Part of the gain is the engine threshold (a downstream rejection), part the cap.",
          f"* **It is not independent evidence.** The sentences are builder-written; the safety margin of the cap is {round(leak_masses[0] / rev['to'], 2)} times against {len(leak_masses)} sentences; the panel was used to choose the value. The independent human-labelled set (`docs/testing/independent_labelling_protocol.md`, EX-01) must be scored with this exact configuration before any claim: it is the only data that can say whether 0.05 is safe on real trainee speech and whether the {still[0]} to {still[-1]} percent of legitimate sentences still missed are recoverable.",
          "* `speech_interpretation` stays OFF and SKIPPED: its suites read the independent result file, which does not exist. Nothing here enables live scoring. No device check was run (Sannan's DC-08 and DC-09 are NOT RUN).", ""]
    return "\n".join(L) + "\n"


def main(argv: list[str]) -> int:
    text = render()
    if "--check" in argv:
        ok = OUT.exists() and OUT.read_text(encoding="utf-8") == text
        print("recall diagnosis page " + ("current" if ok else "OUT OF DATE: run tools/bench/recall_report.py"))
        return 0 if ok else 1
    OUT.write_text(text, encoding="utf-8", newline="\n")
    print("wrote", OUT.relative_to(ROOT).as_posix())
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
